/* Rosalind's Folio VI: the Thornwood Library (round 6, token contract v1.5).
   One idea: a castle library staged like a painted visual novel. Candlelit at night, sunlit by day.
   Palette: night ink #1A1410, walnut #3A2618, parchment #F3E6C8, ink #2B1D14, aged gold #C9A24A,
   oxblood #8B1E2B, candle #F2C66D. Type: Cinzel (display, names), EB Garamond (everything else).
   Signature: ONE gilt frame with corner flourishes on the "speaking" surfaces (assistant pages, the
   VN box, Home widgets, dialogs, Ctrl+K). Everything else: a 1px gold hairline, 6px radius. */

:root {
  --mari-tokens-version: 1;
  --ros-gold: #c9a24a;
  --ros-gold-hi: #e6c77a;
  --ros-ink: #2b1d14;
  --ros-parch: #f3e6c8;
  --ros-oxblood: #8b1e2b;
  --ros-candle: #f2c66d;
  --ros-frame: url("theme:frame-gilt.png");
  --ros-radius: 6px;
  --ros-shadow: 0 10px 28px rgba(8, 4, 2, 0.45);

  --radius: 6px;
  --mari-font-ui: "EB Garamond", "Iowan Old Style", Georgia, serif;
  --mari-font-heading: "Cinzel", "EB Garamond", Georgia, serif;
  --mari-font-chat: "EB Garamond", Georgia, serif;
  --mari-chat-font-size: 18px;
  --mari-text-outline: 0;
  --mari-composer-placeholder: "Write the next line of the tale…";
  --mari-selected-tint: var(--primary);
  --mari-msg-head-rule: 1px solid color-mix(in srgb, var(--ros-gold) 35%, transparent);

  /* top bar: carved walnut strip with gold inlay; tabs sit on small dark plates */
  --mari-top-bar-bg: url("theme:topbar-strip.webp") left center / auto 100% repeat-x, #2a160c;
  --mari-top-bar-plate: rgba(26, 14, 8, 0.72);
  --mari-top-bar-plate-radius: 4px;

  --mari-app-backdrop-size: cover;
  --mari-app-backdrop-position: center;

  /* drifting dust in the candle/sun light */
  --mari-ambient: url("theme:motes.png") 0 0 / 900px repeat;
  --mari-ambient-opacity: 0.4;
  --mari-ambient-blend: screen;
  --mari-ambient-animation: ros-dust 90s linear infinite;

  --mari-cursor: url("theme:cursor.png") 2 2, auto;
  --mari-cursor-pointer: url("theme:cursor.png") 2 2, pointer;
  --mari-icon-send: url("theme:icon-send.png");

  --mari-home-art: none;
  --mari-home-widget-border-width: 4px;
  --mari-home-widget-radius: 0;
  --mari-home-widget-font: "EB Garamond", Georgia, serif;
  --mari-home-widget-title-font: "Cinzel", Georgia, serif;
  --mari-home-widget-title-size: 21px;
  --mari-home-widget-text-size: 16px;
  --mari-home-widget-eyebrow-size: 11px;
  --mari-professor-sprite-scale: 0.9;
  --mari-art-saturation-1: 13%;
  --mari-art-lightness-1: 30%;
  --mari-art-saturation-2: 12%;
  --mari-art-lightness-2: 20%;

  /* v1.4: contract tokens replace the round-4 overrides of internal variables */
  --mari-chat-wash: linear-gradient(180deg, rgba(40, 24, 12, 0.1), transparent 30%, transparent 70%, rgba(40, 24, 12, 0.16));
  --mari-toast-font-size: 15px;
  --mari-min-ui-text: 13px;
  --mari-home-hero-padding: calc(var(--mari-top-bar-height, 48px) + 6px) 22px 14px;
  /* one gilt frame, painted by the app on whatever has the reader's attention:
     the newest reply, Ctrl+K, dialogs, Home's Recent chats */
  --mari-focus-frame: url("theme:frame-gilt.png") 52 / 22px / 0 stretch;
  /* dust drifts in the gutters and between the pages, never over the text */
  --mari-ambient-placement: behind-cards;
  --mari-gutter-clear: 24rem;
  --mari-ambient-mask: var(--mari-gutter-mask);
  --mari-user-avatar-image: url("theme:avatar-reader.png");
  /* the reading column: about 70 characters of Garamond per line, at any window width */
  --ros-measure: 35em;

  /* v1.5 long-reply tokens (round 6: these replace the round-5 workarounds) */
  --mari-chat-column: calc(var(--ros-measure) * 1.125 + 40px);
  --mari-message-measure: var(--ros-measure);
  --mari-chat-line-height: 1.6;
  --mari-dialogue-weight: 400;
  --mari-paragraph-gap: 0.85em;
  --mari-pinned-speaker: on;
  --mari-pinned-speaker-bleed: 16px;
  --mari-pinned-speaker-bg: var(--ros-page);
  --mari-phone-avatar: hidden;
  --mari-vn-fade: 2.25rem;
  --mari-focus-frame-outset: 0;
  --mari-chat-row-art-opacity: 0.2;
  --mari-message-actions: #c9b48e;
  --mari-swipe-counter: #e6c77a;
}
@keyframes ros-dust {
  to {
    background-position: 900px -1800px;
  }
}

/* ============ NIGHT: candlelit ============ */
:root[data-theme="dark"] {
  --background: #1a1410;
  --foreground: #f3e6c8;
  --card: rgba(30, 21, 15, 0.9);
  --card-foreground: #f3e6c8;
