/* Body type: Garamond runs small, so lift its x-height to Inter's size. */
body {
  font-size-adjust: 0.47;
}

/* ================= TOP BAR ================= */
/* the bar is carved wood in both day and night, so its text is always cream */
[data-component="TopBar"] {
  --foreground: #f3e6c8;
  --muted-foreground: #d2c09c;
  --ov-text: #f3e6c8;
  --ov-muted: #d2c09c;
  --ov-dim: #c4b08a;
  --ov-accent: #f2c66d;
  --primary: #e6c77a;
  color: #f3e6c8;
  border-bottom: 1px solid rgba(230, 199, 122, 0.55);
  box-shadow: 0 2px 14px rgba(0, 0, 0, 0.45);
}
:root[data-overhaul="on"] [data-component="TopBar"] .ov-tab__label,
:root[data-overhaul="on"] [data-component="TopBar"] .ov-text-btn {
  font-family: "Cinzel", Georgia, serif;
  font-size-adjust: none;
  letter-spacing: 0.04em;
  color: #f3e6c8;
}
:root[data-overhaul="on"] [data-component="TopBar"] [role="tab"][aria-selected="true"] .ov-tab__label {
  color: #f6dc95;
}

/* ================= SIDEBARS: walnut by night, parchment by day ================= */
[data-component="ChatSidebar"],
[data-component="RightPanelDesktop"],
[data-component="OverhaulLibraryNav"] {
  background: linear-gradient(var(--ros-panel-veil), var(--ros-panel-veil)), var(--ros-panel), var(--sidebar);
  color: var(--ros-text);
}
[data-component="ChatSidebar"] {
  border-right: 1px solid var(--ros-hair);
  box-shadow: inset -1px 0 0 rgba(0, 0, 0, 0.35);
}
[data-component="RightPanelDesktop"] {
  border-left: 1px solid var(--ros-hair);
}
/* the "CHATS" title in display caps */
[data-component="ChatSidebar"] h1,
[data-component="ChatSidebar"] h2 {
  font-family: "Cinzel", Georgia, serif;
  font-size-adjust: none;
  letter-spacing: 0.06em;
}
/* chat rows: the open chat gets a gold hairline + a candle-gold marker, not a frame */
[data-chat-row] {
  border-radius: var(--ros-radius);
  font-size: 16px;
}
[data-chat-row][data-selected="true"] {
  background: linear-gradient(90deg, rgba(201, 162, 74, 0.22), rgba(201, 162, 74, 0.06));
  box-shadow: inset 0 0 0 1px var(--ros-hair);
}
/* sidebar fields (search, sort) sit in the wood like inlays */
[data-component="ChatSidebar"] input,
[data-component="ChatSidebar"] select,
[data-component="ChatSidebar"] button[aria-haspopup] {
  background-color: var(--ros-field);
}

/* ================= HOME ================= */
[data-mari-part="home-widget"] {
  background: var(--mari-home-widget-bg);
  background-origin: border-box;
  border-style: solid;
  border-color: transparent;
  border-image: var(--ros-frame) 52 / 20px / 0 stretch;
  box-shadow: var(--ros-shadow);
}
/* Home's hero line sits on a calm plate, not straight on the painting */
.mari-home-hero {
  background: var(--ros-hero-plate);
  border-bottom: 1px solid var(--ros-hair);
  backdrop-filter: blur(8px);
  margin: -14px -14px 6px;
  border-radius: 0 0 6px 6px;
}
[data-mari-part="home-widget-eyebrow"] {
  font-family: "Cinzel", Georgia, serif;
  font-size-adjust: none;
  letter-spacing: 0.14em;
}
[data-mari-part="home-widget-title"] {
  font-size-adjust: none;
  letter-spacing: 0.03em;
}

/* ================= ROLEPLAY: pages in the book ================= */
/* Every story page is parchment with a fine double gold rule. The page you are reading now (the
   newest reply) gets the gilt frame from the app's focus-frame slot. Pages are capped to a book
   measure (about 70 characters a line) so a 900-word reply reads like a book, not a banner. */
.mari-rp-bubble {
  background: var(--ros-page);
  color: var(--ros-page-ink);
  border-radius: 2px;
  /* longhands, so the app's focus-frame border-image is not reset by the shorthand */
  border-width: 22px;
  border-style: solid;
  border-color: transparent;
  /* older pages: a single gold rule inset in the margin */
  outline: 1px solid color-mix(in srgb, var(--ros-gold) 60%, transparent);
  outline-offset: -7px;
  box-shadow: var(--ros-shadow);
  background-origin: border-box;
  position: relative;
  overflow: visible;
  --mari-dialogue-color: var(--ros-page-quote);
  --mari-message-time: var(--ros-page-time);
}
/* the newest reply: the gilt frame replaces the double rule */
[data-mari-part="message"][data-latest] .mari-rp-bubble:not(.mari-rp-bubble--user) {
  outline: 0;
}
.mari-rp-bubble .mari-message-content {
  color: var(--ros-page-ink);
  text-wrap: pretty;
}
/* real **bold** is emphasis in the page's own ink, so it never reads as speech
   (speech itself is regular-weight oxblood through --mari-dialogue-weight / -color) */
.mari-rp-bubble .mari-message-content strong:not([data-mari-part="dialogue"]) {
  font-weight: 650;
  color: var(--ros-page-ink);
}
.mari-rp-bubble .mari-message-content em {
  color: var(--ros-page-dim);
}
/* lists: gilt Cinzel numerals hung in the margin */
.mari-rp-bubble .mari-message-content :is(ol, ul) {
  padding-left: 1.9em;
  margin: 0.35em 0 0.5em;
}
.mari-rp-bubble .mari-message-content li {
  margin: 0.2em 0;
  padding-left: 0.2em;
}
.mari-rp-bubble .mari-message-content ol > li::marker {
  font-family: "Cinzel", Georgia, serif;
  font-size: 0.85em;
  font-weight: 600;
  color: #8a5a14;
}
.mari-rp-bubble .mari-message-content ul > li::marker {
  color: #8a5a14;
}
/* --- is a scene break: a hairline, a gilt lozenge, a hairline */
:is(.mari-rp-bubble, [data-mari-part="message"][data-vn]) hr {
  border: 0;
  height: 22px;
  margin: 0.9em auto;
  width: min(70%, 22em);
  overflow: visible;
  position: relative;
  background: linear-gradient(90deg, transparent, var(--ros-rule) 16%, var(--ros-rule) 43%, transparent 43%, transparent 57%, var(--ros-rule) 57%, var(--ros-rule) 84%, transparent) center / 100% 1px no-repeat;
}
:is(.mari-rp-bubble, [data-mari-part="message"][data-vn]) hr::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 11px;
  height: 11px;
  translate: -50% -50%;
  rotate: 45deg;
  border: 1.5px solid #a8822f;
  background: radial-gradient(circle, var(--ros-oxblood) 0 2px, transparent 2.6px), #e6c77a;
  box-shadow: 0 0 0 3px color-mix(in srgb, #e6c77a 25%, transparent);
}
/* the name line stays with you while you read down a long page (the app pins it: --mari-pinned-speaker);
   the theme only gives it a gold rule and a soft fade so lines slide under it, not through it */
.mari-rp-bubble:not(.mari-rp-bubble--user) [data-mari-part="header"][data-placement="inside"] {
  padding-top: 8px;
  padding-bottom: 6px;
  margin-bottom: 6px;
  border-bottom: 1px solid color-mix(in srgb, var(--ros-gold) 45%, transparent);
  box-shadow: 0 10px 8px -6px rgba(240, 226, 193, 0.95);
}
.mari-rp-bubble .mari-message-name {
  font-family: "Cinzel", Georgia, serif;
  font-size-adjust: none;
  font-size: 15px;
  letter-spacing: 0.06em;
  color: #6b3d12;
}
.mari-rp-bubble [data-mari-part="time"] {
  font-size: 13px;
}
.mari-rp-bubble button {
  color: #6b3d12;
}
/* the player's own lines: a plainer page with a hairline (the frame belongs to the story) */
.mari-rp-bubble--user {
  background: var(--ros-user-page);
  color: var(--ros-user-ink);
  border: 1px solid var(--ros-hair);
  border-image: none;
  outline: 0;
  border-radius: var(--ros-radius);
  box-shadow: var(--ros-shadow);
  padding: 16px 20px;
  --mari-dialogue-color: var(--ros-user-quote);
  --mari-message-time: var(--ros-user-dim);
}
.mari-rp-bubble--user .mari-message-content {
  color: var(--ros-user-ink);
}
.mari-rp-bubble--user .mari-message-content strong:not([data-mari-part="dialogue"]) {
  color: var(--ros-user-ink);
}
.mari-rp-bubble--user .mari-message-content em {
  color: var(--ros-user-dim);
}
.mari-rp-bubble--user [data-mari-part="header"][data-placement="inside"] {
  margin: 0 0 6px;
  padding: 0 0 4px;
  background: none;
  box-shadow: none;
  border-bottom: 1px solid color-mix(in srgb, var(--ros-gold) 40%, transparent);
}
.mari-rp-bubble--user .mari-message-name,
.mari-rp-bubble--user button {
  color: var(--ros-user-quote);
}
/* names and times that sit on the art (narrow screens put the name line above the page):
   they get a small plate so they read on any part of the picture */
[data-chat-mode="roleplay"] [data-mari-part="message"]:not([data-vn]) [data-mari-part="header"]:not(.mari-rp-bubble [data-mari-part="header"]) {
  background: var(--ros-name-plate);
  border-radius: 4px;
  padding: 1px 8px;
  width: fit-content;
  --mari-message-time: var(--ros-name-ink);
}
[data-chat-mode="roleplay"] [data-mari-part="message"]:not([data-vn]) [data-mari-part="header"]:not(.mari-rp-bubble [data-mari-part="header"]) > * {
  color: var(--ros-name-ink);
  text-shadow: none;
}
[data-chat-mode="roleplay"] [data-mari-part="message"]:not([data-vn]) [data-mari-part="header"]:not(.mari-rp-bubble [data-mari-part="header"]) .mari-message-name {
  font-family: "Cinzel", Georgia, serif;
  font-size-adjust: none;
  color: var(--ros-name-gold);
}
/* avatars: a gold ring */
[data-chat-mode="roleplay"] [data-mari-part="avatar"] > * {
  box-shadow: 0 0 0 2px var(--ros-gold), 0 0 0 4px rgba(26, 14, 8, 0.6), 0 4px 10px rgba(0, 0, 0, 0.5);
}
/* no portrait: painted medallions instead of the stock robot and person icons and the initials,
   everywhere the app shows an empty avatar (messages, chat rows, Home, the message box) */
[data-mari-part="avatar-placeholder"] {
  background: url("theme:avatar-unwritten.png") center / cover no-repeat !important;
  color: transparent;
  font-size: 0;
  animation: none;
}
[data-mari-part="avatar-placeholder"][data-role="user"] {
  background-image: url("theme:avatar-reader.png") !important;
}
[data-mari-part="avatar-placeholder"] > svg {
  display: none;
}
[data-mari-part="message"] .mari-chrome-accent-tile {
  background: radial-gradient(circle at 35% 30%, #5a3a22, #24160e 75%);
  color: var(--ros-gold-hi);
  --tw-ring-color: var(--ros-gold);
  animation: none;
}
/* the newest reply is sealed: the seal sits in the page's bottom margin, never on the words */
[data-mari-part="message"][data-latest] .mari-rp-bubble:not(.mari-rp-bubble--user) > div {
  padding-bottom: 34px;
}
[data-mari-part="message"][data-latest] .mari-rp-bubble:not(.mari-rp-bubble--user)::after {
  content: "";
  position: absolute;
  right: 8px;
  bottom: 2px;
  width: 38px;
  height: 38px;
  pointer-events: none;
  background: url("theme:seal.png") center / contain no-repeat;
  transform: rotate(-10deg);
  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.45));
}

/* ================= COMPOSER ================= */
[data-mari-part="composer"] .mari-chat-input-box {
  background: linear-gradient(var(--ros-panel-veil), var(--ros-panel-veil)), var(--ros-panel);
  border: 1px solid var(--ros-hair);
  border-radius: var(--ros-radius);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.25), var(--ros-shadow);
  color: var(--ros-text);
}
[data-mari-part="composer"] textarea {
  color: var(--ros-text);
  font-size: 18px;
}
[data-mari-part="composer"] textarea::placeholder {
  color: var(--ros-dim);
  font-style: italic;
  opacity: 1;
}
[data-mari-part="composer"] button {
  color: var(--ros-dim);
}
/* send = a wax seal you press */
[data-mari-part="composer"] .mari-chat-send-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
}
[data-mari-part="composer"] .mari-chat-send-btn svg {
  width: 34px;
  height: 34px;
  filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.4));
}
[data-mari-part="composer"] .mari-chat-send-btn:hover {
  background: rgba(201, 162, 74, 0.16);
}

/* ================= VISUAL NOVEL ================= */
[data-mari-part="vn-sprite"][data-character="seraphine-of-thornwood"] {
  background: url("theme:sprite-seraphine.webp") 50% 100% / auto 90% no-repeat;
  filter: drop-shadow(0 0 24px rgba(0, 0, 0, 0.55));
}
[data-mari-part="message"][data-vn] {
  background: none;
  border-radius: 0;
  box-shadow: none;
  /* the dialogue box is a page of the same book: walnut by candlelight, parchment by day, in the gilt frame */
  background: var(--ros-vn-page);
  background-origin: border-box;
  border-width: 22px;
  border-style: solid;
  border-color: transparent;
  border-image: var(--ros-frame) 52 / 22px / 0 stretch;
  padding: 10px 18px 4px;
  color: var(--ros-vn-ink);
  --mari-dialogue-color: var(--ros-vn-quote);
}
[data-mari-part="message"][data-vn] * {
  -webkit-text-stroke: 0;
}
/* the dialogue box keeps a book measure too, and a long paragraph scrolls inside it with a soft
   fade at the foot (instead of a hard cut mid-line) */
[data-mari-part="message"][data-vn] .mari-message-content {
  max-inline-size: 740px;
  padding-bottom: 6px;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--ros-gold) 70%, transparent) transparent;
}
[data-mari-part="message"][data-vn] :is(p, span) {
  color: var(--ros-vn-ink);
  font-size: 20px;
}
[data-mari-part="message"][data-vn] strong:not([data-mari-part="dialogue"]) {
  font-weight: 650;
  color: var(--ros-vn-ink);
}
[data-mari-part="message"][data-vn] em {
  color: var(--ros-vn-dim);
}
[data-mari-part="message"][data-vn] hr {
  --ros-rule: color-mix(in srgb, var(--ros-gold) 75%, transparent);
}
/* a scene break opens its page (the app keeps --- with the paragraph after it) */
[data-mari-part="message"][data-vn] hr:first-child {
  margin: 0.1em auto 0.6em;
}
[data-mari-part="message"][data-vn] [data-mari-part="header"],
[data-mari-part="message"][data-vn] [data-mari-part="header"] * {
  font-family: "Cinzel", Georgia, serif;
  font-size-adjust: none;
  letter-spacing: 0.08em;
  color: var(--ros-vn-quote);
}
[data-mari-part="message"][data-vn] [data-mari-part="avatar"] {
  box-shadow: 0 0 0 2px var(--ros-gold), 0 0 0 5px rgba(26, 14, 8, 0.55);
  border-radius: 4px;
}
/* paging: a page number in Cinzel between two small gilt-edged buttons (v1.5 parts) */
[data-mari-part="vn-nav"] {
  font-size: 15px;
  color: var(--ros-vn-ink);
  border: 1px solid color-mix(in srgb, var(--ros-gold) 45%, transparent);
  border-radius: 4px;
  padding: 3px 10px;
}
[data-mari-part="vn-nav"]:hover {
  background: color-mix(in srgb, var(--ros-gold) 16%, transparent);
}
[data-mari-part="vn-nav"]:disabled {
  border-color: transparent;
}
[data-mari-part="vn-counter"] {
  font-family: "Cinzel", Georgia, serif;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--ros-vn-quote);
  opacity: 1;
}
[data-mari-part="vn-counter"]::before,
[data-mari-part="vn-counter"]::after {
  content: "";
  display: inline-block;
  width: 26px;
  height: 1px;
  margin: 0 10px;
  vertical-align: middle;
  background: color-mix(in srgb, var(--ros-gold) 60%, transparent);
}
:root[data-theme="dark"] [data-mari-part="vn-nav"] {
  --ros-vn-ink: #f3e6c8;
}

/* ================= CONVERSATION (texting): stock bubbles, library colours ================= */
/* texting is a quick exchange, not a page: no gilt frame on the newest line */
[data-chat-mode="conversation"] [data-mari-part="message"][data-latest] {
  border-image: none;
}
[data-chat-mode="conversation"] .mari-messages-scroll {
  background: linear-gradient(90deg, transparent, var(--mari-page-veil) 6%, var(--mari-page-veil) 94%, transparent) !important;
  position: relative;
  z-index: 1;
}
[data-chat-mode="conversation"] .mari-message-name,
[data-chat-mode="conversation"] [data-mari-part="header"] :is(span, button):first-child {
  font-family: "Cinzel", Georgia, serif;
  font-size-adjust: none;
  font-size: 14px;
  letter-spacing: 0.04em;
  color: var(--ov-accent);
}

/* ================= GAME ================= */
[data-mari-part="message"][data-game-narration],
[data-chat-mode="game"] .mari-game-narration-surface {
  background: linear-gradient(rgba(26, 17, 12, 0.9), rgba(18, 12, 9, 0.92)), url("theme:walnut.webp") 0 0 / 256px 512px;
  border: 22px solid transparent;
  border-image: var(--ros-frame) 52 / 22px / 0 stretch;
  border-radius: 0;
  color: var(--ros-vn-ink);
}
/* by day the narrator writes on parchment too */
:root[data-theme="light"] :is([data-mari-part="message"][data-game-narration], [data-chat-mode="game"] .mari-game-narration-surface) {
  background: var(--ros-page);
  color: var(--ros-page-ink);
}
:root[data-theme="light"] [data-chat-mode="game"] .mari-game-narration-surface .game-narration-prose {
  color: var(--ros-page-ink);
}
[data-chat-mode="game"] .game-narration-prose {
  font-family: "EB Garamond", Georgia, serif;
  font-size: 19px;
  color: var(--ros-vn-ink);
  background: transparent;
}

/* ================= PAGES, PANELS, DIALOGS, CTRL+K, TOASTS ================= */
/* a character card with no picture shows the unwritten book, not a teal gradient */
:root {
  --mari-card-art-placeholder: url("theme:avatar-unwritten.png") center 38% / 82% no-repeat, #2b1d14;
}
[data-mari-part="card-art"][data-placeholder] {
  box-shadow: inset 0 0 0 1px var(--ros-hair);
}
[data-mari-part="card-art"][data-placeholder] > svg {
  display: none;
}
[data-component="OverhaulSettingsPage"] h1,
[data-component="OverhaulLibraryPage"] h1,
[data-component="OverhaulEditorHead"] h1 {
  font-family: "Cinzel", Georgia, serif;
  font-size-adjust: none;
  letter-spacing: 0.04em;
}
[data-component="OverhaulEditorHead"] {
  background: linear-gradient(90deg, rgba(201, 162, 74, 0.16), transparent 60%);
  border-bottom: 1px solid var(--ros-hair);
}
:is(.mari-modal-panel, [data-component="GlobalOmnibar.Panel"], [role="dialog"].mari-window) {
  /* the gilt frame itself comes from --mari-focus-frame */
  border-width: 22px;
  border-style: solid;
  border-color: transparent;
  border-radius: 0;
  background: linear-gradient(var(--ros-panel-veil), var(--ros-panel-veil)), var(--ros-panel), var(--popover);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55);
}
.mari-modal-panel :is(h2, h3):first-of-type {
  font-family: "Cinzel", Georgia, serif;
  font-size-adjust: none;
  letter-spacing: 0.05em;
  color: var(--ov-accent);
}
:is(.mari-drawer, [role="menu"], [data-radix-popper-content-wrapper] > *, [data-sonner-toast]) {
  background: linear-gradient(var(--ros-panel-veil), var(--ros-panel-veil)), var(--ros-panel), var(--popover);
  border: 1px solid var(--ros-hair);
  border-radius: var(--ros-radius);
  color: var(--ros-text);
}

[data-component="GlobalOmnibar"] .result-type-icon svg,
[data-component="GlobalOmnibar"] .result-type-icon + * svg {
  color: var(--ov-accent);
}

[data-sonner-toast] [data-title] {
  font-weight: 600;
}
[data-sonner-toast] [data-close-button] {
  background: var(--popover);
  border-color: var(--ros-hair);
  color: var(--ros-text);
}


/* ================= COMFORT ================= */
@media (max-width: 640px) {
  .mari-rp-bubble:not(.mari-rp-bubble--user) {
    border-width: 14px;
    border-image-width: 14px;
  }
  [data-mari-part="home-widget"] {
    border-image-width: 14px;
  }
  .mari-rp-bubble:not(.mari-rp-bubble--user) {
    outline-offset: -5px;
  }
  [data-mari-part="message"][data-vn] {
    border-width: 14px;
    border-image-width: 14px;
    padding: 6px 8px 2px;
  }
  /* on a phone the sprite already shows who speaks: the box gives the portrait's width to the text,
     and grows a little so a long paragraph needs less scrolling */
  [data-mari-part="message"][data-vn] > [data-mari-part="avatar"] {
    display: none;
  }
  /* the box takes the lower half, so Seraphine stands higher: her face stays above it */
  [data-mari-part="vn-sprite"][data-character="seraphine-of-thornwood"] {
    background-size: 72% auto;
    background-position: 50% 0;
  }
  [data-mari-part="message"][data-vn] .mari-message-content {
    max-height: min(38dvh, 21rem) !important;
  }
  [data-mari-part="message"][data-vn] :is(p, span) {
    font-size: 17.5px;
  }
  [data-mari-part="vn-nav"] span {
    display: none;
  }
}

/* Portrait screens (phones, tablets held upright): the tall library hall instead of a cropped landscape. */
@media (max-aspect-ratio: 3/4) {
  :root[data-theme="dark"] {
    --mari-stage-empty-bg: linear-gradient(rgba(16, 10, 7, 0.55), rgba(16, 10, 7, 0.75)), url("theme:backdrop-portrait-night.webp") center / cover no-repeat;
    --mari-app-backdrop-layers:
      radial-gradient(ellipse at 50% 50%, rgba(10, 6, 4, 0) 40%, rgba(10, 6, 4, 0.4) 100%),
      url("theme:backdrop-portrait-night.webp") center / cover no-repeat, #1a1410;
  }
  :root[data-theme="light"] {
    --mari-stage-empty-bg: linear-gradient(rgba(250, 240, 220, 0.25), rgba(60, 40, 20, 0.25)), url("theme:backdrop-portrait-day.webp") center / cover no-repeat;
    --mari-app-backdrop-layers:
      radial-gradient(ellipse at 50% 50%, rgba(250, 238, 210, 0) 35%, rgba(90, 58, 30, 0.28) 100%),
      url("theme:backdrop-portrait-day.webp") center / cover no-repeat, #efe3c8;
  }
}
